def lis_length(nums):
    def best(i):
        top = 1
        for j in range(i + 1, len(nums)):
            if nums[j] > nums[i]:
                length = 1 + best(j)
                if length > top:
                    top = length
        return top
    return max((best(i) for i in range(len(nums))), default=0)
